mapper.sql:
and (
    o.reporter_id = #{currentUserId}
    or o.assignee_id = #{currentUserId}

        or 1 = 1


        or d.laboratory_id in

            #{labId}


)

mapper.select:
select from lab_repair_order o join lab_device d on d.id = o.device_id and d.del_flag = '0' where o.del_flag = '0'
and o.repair_no = #{query.repairNo}
and o.device_id = #{query.deviceId}
and o.status = #{query.status}
order by
o.repair_no o.status o.id o.create_time
asc desc
